1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const BLOCK_SIZE = 3;
57	const BLOCK_BASE_PREMIUM = 60;
58	const CURSE_SURCHARGE_PERCENT = 50;
59	
60	const basePremiumOf = (item: Item): number =>
61	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
62	
63	const itemSurcharge = (item: Item): number =>
64	  item.cursed ? percentOf(basePremiumOf(item), CURSE_SURCHARGE_PERCENT) : 0;
65	
66	const sumItemSurcharges = (items: Item[]): number =>
67	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
68	
69	const groupByType = (items: Item[]): Item[][] => [
70	  ...items
71	    .reduce(
72	      (groups, item) =>
73	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
74	      new Map<string, Item[]>(),
75	    )
76	    .values(),
77	];
78	
79	const basePremiumOfGroup = (group: Item[]): number => {
80	  if (group.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
81	  return group.reduce((sum, item) => sum + basePremiumOf(item), 0);
82	};
83	
84	const policyBasePremium = (items: Item[]): number =>
85	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
86	
87	const quotePremium = (items: Item[]): number => {
88	  const policyBase = policyBasePremium(items);
89	  const premiumBeforeFee =
90	    policyBase +
91	    sumItemSurcharges(items) +
92	    percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
93	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
94	};
95	
96	const runStep = (step: Step): StepResult => {
97	  if (step.op === "quote") return { premium: quotePremium(step.items) };
98	  throw new Error("claim steps are not implemented yet");
99	};
100	
101	export const runScenario = (scenario: Scenario): ScenarioResult => ({
102	  results: scenario.steps.map(runStep),
103	});
